-- Template library v2: categories, 20+ professionally designed built-in templates (pub_id NULL = shared library).
-- Posts now store only their own style overrides (style) + template_id; effective style = publication ⊕ template ⊕ post.
ALTER TABLE templates ADD COLUMN category TEXT NOT NULL DEFAULT '';
UPDATE templates SET category = 'Digest' WHERE id IN ('tpl_builtin_1');
UPDATE templates SET category = 'Editorial' WHERE id IN ('tpl_builtin_2','tpl_builtin_5');
UPDATE templates SET category = 'Curation' WHERE id IN ('tpl_builtin_3');
UPDATE templates SET category = 'Business' WHERE id IN ('tpl_builtin_4','tpl_builtin_6');
UPDATE templates SET category = 'Welcome' WHERE id IN ('tpl_builtin_7');
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_weekly_brief', NULL, 'The weekly brief', 'post', 'Editor’s note, lead story, three quick reads, sponsor slot and a referral nudge — the classic weekly format.', '{"blocks":[{"id":"week1","type":"paragraph","data":{"html":"Hey {{subscriber.first_name|there}} 👋"}},{"id":"week2","type":"paragraph","data":{"html":"Here’s everything worth knowing this week, in about five minutes. If you only read one thing, make it the lead story."}},{"id":"week5","type":"section","data":{"blocks":[{"id":"week3","type":"heading","data":{"level":4,"html":"In this issue"}},{"id":"week4","type":"list","data":{"ordered":false,"items":["<b>The lead:</b> one-line teaser for the main story","<b>Quick reads:</b> three links worth your time","<b>Tool of the week:</b> something we actually use"]}}],"style":{"bg":"#eff6ff","padding":18,"radius":10}}},{"id":"week6","type":"heading","data":{"level":2,"html":"The lead story"}},{"id":"week7","type":"paragraph","data":{"html":"Open with what happened in one or two sentences. Then explain why it matters to <i>your</i> reader — the second-order effect most coverage misses."}},{"id":"week8","type":"paragraph","data":{"html":"Close the section with what to watch for next, or one concrete thing the reader can do with this information."}},{"id":"week9","type":"button","data":{"label":"Read the full story →","url":"https://example.com","align":"left"}},{"id":"weeka","type":"ad","data":{"label":"Together with","headline":"Your sponsor’s headline goes here","body":"Two sentences on what the sponsor does and why it is useful to this audience. Keep it honest and specific.","url":"https://example.com","cta":"Learn more"}},{"id":"weekb","type":"heading","data":{"level":2,"html":"Three quick reads"}},{"id":"weekc","type":"list","data":{"ordered":true,"items":["<b><a href=\"https://example.com\">Headline of the first link</a></b> — one sentence on why it’s worth the click.","<b><a href=\"https://example.com\">Headline of the second link</a></b> — the single most useful takeaway.","<b><a href=\"https://example.com\">Headline of the third link</a></b> — a surprising detail or number."]}},{"id":"weekd","type":"heading","data":{"level":2,"html":"Tool of the week"}},{"id":"weekf","type":"section","data":{"blocks":[{"id":"weeke","type":"paragraph","data":{"html":"<b>Tool name</b> — what it does, who it’s for and the one feature that sold us. <a href=\"https://example.com\">Try it →</a>"}}],"style":{"bg":"#f8fafc","padding":18,"radius":10,"border_width":1,"border_color":"#e2e8f0"}}},{"id":"weekg","type":"divider","data":{"style":"dots"}},{"id":"weekh","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}},{"id":"weeki","type":"paragraph","data":{"html":"That’s it for this week. Hit reply and tell me what you’d like to see more of — I read every response."}},{"id":"weekj","type":"paragraph","data":{"html":"— {{publication.name}}"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.65,"text":"#0f172a","muted":"#64748b","bg":"#eef2f7","content_bg":"#ffffff","accent":"#2563eb","link":"#1d4ed8","button_bg":"#0f172a","button_text":"#ffffff","border":"#e2e8f0","radius":10,"width":640,"spacing":16},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#0f172a","accent":"#2563eb","accent_text":"#ffffff"}}', 0, 'Digest', 1793000000000, 1793000000000);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_news_digest', NULL, 'Morning news digest', 'post', 'Fast, scannable daily briefing with a table of contents, topic sections, an “in other news” rundown and a reader poll.', '{"blocks":[{"id":"news1","type":"paragraph","data":{"html":"Good morning, {{subscriber.first_name|there}}. Today is {{date}} — here’s what you need to know before your first meeting."}},{"id":"news2","type":"toc","data":{}},{"id":"news3","type":"heading","data":{"level":2,"html":"🌍 World"}},{"id":"news4","type":"paragraph","data":{"html":"<b>Headline in bold.</b> Two to three sentences summarizing the story: what happened, who is involved, and the immediate consequence. <a href=\"https://example.com\">Source</a>"}},{"id":"news5","type":"paragraph","data":{"html":"<b>Second world story.</b> Keep each summary tight. One idea per paragraph so readers can skim. <a href=\"https://example.com\">Source</a>"}},{"id":"news6","type":"heading","data":{"level":2,"html":"💼 Business"}},{"id":"news7","type":"paragraph","data":{"html":"<b>Market-moving story.</b> Lead with the number, then the context. Why did it move, and what does it signal? <a href=\"https://example.com\">Source</a>"}},{"id":"news8","type":"ad","data":{"label":"Presented by","headline":"A one-line sponsor message","body":"Short, native-feeling copy that matches the tone of the digest.","url":"https://example.com","cta":"Learn more"}},{"id":"news9","type":"heading","data":{"level":2,"html":"🔬 Tech & science"}},{"id":"newsa","type":"paragraph","data":{"html":"<b>Breakthrough or launch.</b> Explain it like you would to a smart friend outside the field. <a href=\"https://example.com\">Source</a>"}},{"id":"newsb","type":"heading","data":{"level":2,"html":"⚡ In other news"}},{"id":"newsc","type":"list","data":{"ordered":false,"items":["One-line item with a <a href=\"https://example.com\">link</a>","One-line item with a <a href=\"https://example.com\">link</a>","One-line item with a <a href=\"https://example.com\">link</a>","One-line item with a <a href=\"https://example.com\">link</a>"]}},{"id":"newsd","type":"heading","data":{"level":3,"html":"Today’s question"}},{"id":"newse","type":"paragraph","data":{"html":"Add a poll below to ask readers one quick question — results show on the web version."}},{"id":"newsf","type":"poll","data":{"poll_id":""}},{"id":"newsg","type":"divider","data":{"style":"line"}},{"id":"newsh","type":"referral","data":{"title":"Forwarded this? Share it and earn rewards"}}]}', '{"email":{"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.55,"text":"#111111","muted":"#6b6b6b","bg":"#f5f5f4","content_bg":"#ffffff","accent":"#dc2626","link":"#b91c1c","button_bg":"#dc2626","button_text":"#ffffff","border":"#e7e5e4","radius":4,"width":620,"spacing":14},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#111111","accent":"#dc2626","accent_text":"#ffffff"}}', 0, 'Digest', 1793000000001, 1793000000001);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_link_pack', NULL, 'Curated link pack', 'post', 'Hand-picked links grouped into Read / Watch / Listen / Use, each with a one-line take, plus recommendations.', '{"blocks":[{"id":"link1","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|friend}} — I read a lot so you don’t have to. Here are the best things I found this week."}},{"id":"link5","type":"section","data":{"blocks":[{"id":"link2","type":"heading","data":{"level":3,"html":"⭐ The one link"}},{"id":"link3","type":"paragraph","data":{"html":"<b><a href=\"https://example.com\">The single best thing I read this week</a></b>"}},{"id":"link4","type":"paragraph","data":{"html":"Three sentences on why it deserves your undivided attention, and the idea you’ll keep thinking about."}}],"style":{"bg":"#ecfdf5","padding":22,"radius":12}}},{"id":"link6","type":"heading","data":{"level":3,"html":"📖 Read"}},{"id":"link7","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\"><b>Article title</b></a> — your one-line take, not the article’s summary.","<a href=\"https://example.com\"><b>Article title</b></a> — what surprised you.","<a href=\"https://example.com\"><b>Article title</b></a> — who should read it."]}},{"id":"link8","type":"heading","data":{"level":3,"html":"📺 Watch"}},{"id":"link9","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\"><b>Video title</b></a> (12 min) — the best part starts at 4:30."]}},{"id":"linka","type":"heading","data":{"level":3,"html":"🎧 Listen"}},{"id":"linkb","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\"><b>Episode title</b></a> — the one idea worth the hour."]}},{"id":"linkc","type":"ad","data":{"label":"A word from our sponsor","headline":"Your sponsor’s headline goes here","body":"Two sentences on what the sponsor does and why it is useful to this audience. Keep it honest and specific.","url":"https://example.com","cta":"Learn more"}},{"id":"linkd","type":"heading","data":{"level":3,"html":"🛠 Use"}},{"id":"linke","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\"><b>Tool name</b></a> — what it replaces in your workflow.","<a href=\"https://example.com\"><b>Tool name</b></a> — free tier is generous."]}},{"id":"linkf","type":"divider","data":{"style":"stars"}},{"id":"linkg","type":"recommendations","data":{"title":"More newsletters worth your inbox","limit":3}},{"id":"linkh","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":17,"line_height":1.6,"text":"#1c1917","muted":"#78716c","bg":"#faf7f2","content_bg":"#ffffff","accent":"#059669","link":"#047857","button_bg":"#065f46","button_text":"#ffffff","border":"#e7e0d3","radius":12,"width":620,"spacing":16},"web":{"font":"Lora, Georgia, serif","heading_font":"''DM Sans'', sans-serif","text":"#1c1917","accent":"#059669","accent_text":"#ffffff"}}', 0, 'Curation', 1793000000002, 1793000000002);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_essay', NULL, 'Long-form essay', 'post', 'A focused, beautifully typeset essay: hook, argument, pull quote, counterpoint, footnotes and an optional premium section.', '{"blocks":[{"id":"essa1","type":"paragraph","data":{"html":"Open with a scene, a question or a surprising fact. The first two sentences decide whether anyone reads the third — make them concrete."}},{"id":"essa2","type":"paragraph","data":{"html":"Then widen the lens: what is this essay really about, and why now?"}},{"id":"essa3","type":"heading","data":{"level":2,"html":"I. The argument"}},{"id":"essa4","type":"paragraph","data":{"html":"State your thesis plainly in one sentence. Then support it with evidence, examples and your own experience<span data-footnote=\"Cite your sources: author, title, link.\"></span>."}},{"id":"essa5","type":"quote","data":{"html":"The single most memorable line of the essay, set apart so skimmers catch it.","cite":"","style":{"variant":"pull","italic":true}}},{"id":"essa6","type":"heading","data":{"level":2,"html":"II. The strongest objection"}},{"id":"essa7","type":"paragraph","data":{"html":"Steelman the opposing view. Readers trust writers who take the other side seriously — then explain precisely where it breaks down."}},{"id":"essa8","type":"heading","data":{"level":2,"html":"III. What follows"}},{"id":"essa9","type":"paragraph","data":{"html":"Land the plane: what should the reader think, feel or do differently now? End on an image or a question, not a summary."}},{"id":"essaa","type":"paywall","data":{}},{"id":"essab","type":"heading","data":{"level":2,"html":"For members: the notes behind the essay"}},{"id":"essac","type":"paragraph","data":{"html":"Premium readers get the research notes, the cut sections and the reading list that shaped this piece."}},{"id":"essad","type":"divider","data":{"style":"line"}},{"id":"essae","type":"paragraph","data":{"html":"<i>If this made you think, forward it to one person who would disagree with it.</i>","align":"center"}},{"id":"essaf","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":19,"line_height":1.75,"text":"#1f1d1a","muted":"#7a746b","bg":"#f7f3ec","content_bg":"#fffdf9","accent":"#9a3412","link":"#9a3412","button_bg":"#1f1d1a","button_text":"#fffdf9","border":"#e8dfd0","radius":2,"width":620,"spacing":20},"web":{"font":"Lora, Georgia, serif","heading_font":"''Playfair Display'', Georgia, serif","text":"#1f1d1a","bg":"#fffdf9","accent":"#9a3412","accent_text":"#ffffff"}}', 0, 'Editorial', 1793000000003, 1793000000003);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_interview', NULL, 'Interview / Q&A', 'post', 'Guest intro card, key takeaways, a clean Q&A with pull quotes, a mid-roll sponsor and a “where to find them” box.', '{"blocks":[{"id":"inte4","type":"section","data":{"blocks":[{"id":"inte1","type":"paragraph","data":{"html":"<b>THIS WEEK’S GUEST</b>"}},{"id":"inte2","type":"heading","data":{"level":2,"html":"Guest Name, Role at Company"}},{"id":"inte3","type":"paragraph","data":{"html":"One paragraph on who they are, what they’ve built, and why their perspective matters right now."}}],"style":{"bg":"#fdf2f8","padding":22,"radius":12}}},{"id":"inte5","type":"heading","data":{"level":3,"html":"Key takeaways"}},{"id":"inte6","type":"list","data":{"ordered":false,"items":["<b>Takeaway one</b> — the counter-intuitive idea","<b>Takeaway two</b> — the practical tactic","<b>Takeaway three</b> — the prediction"]}},{"id":"inte7","type":"divider","data":{"style":"line"}},{"id":"inte8","type":"paragraph","data":{"html":"<b>Q: Let’s start at the beginning. How did you get here?</b>"}},{"id":"inte9","type":"paragraph","data":{"html":"Answer in the guest’s own words. Edit for clarity, not for voice."}},{"id":"intea","type":"paragraph","data":{"html":"<b>Q: What’s something most people get wrong about your field?</b>"}},{"id":"inteb","type":"paragraph","data":{"html":"Answer."}},{"id":"intec","type":"quote","data":{"html":"The most quotable line from the interview goes here.","cite":"Guest Name","style":{"variant":"box","border_color":"#db2777","bg":"#fff1f7"}}},{"id":"inted","type":"ad","data":{"label":"Together with","headline":"Your sponsor’s headline goes here","body":"Two sentences on what the sponsor does and why it is useful to this audience. Keep it honest and specific.","url":"https://example.com","cta":"Learn more"}},{"id":"intee","type":"paragraph","data":{"html":"<b>Q: What does a typical week look like for you?</b>"}},{"id":"intef","type":"paragraph","data":{"html":"Answer."}},{"id":"integ","type":"paragraph","data":{"html":"<b>Q: What advice would you give someone starting out today?</b>"}},{"id":"inteh","type":"paragraph","data":{"html":"Answer."}},{"id":"intek","type":"section","data":{"blocks":[{"id":"intei","type":"heading","data":{"level":4,"html":"Where to find Guest Name"}},{"id":"intej","type":"list","data":{"ordered":false,"items":["Website: <a href=\"https://example.com\">example.com</a>","Newsletter: <a href=\"https://example.com\">subscribe here</a>","Social: <a href=\"https://example.com\">@handle</a>"]}}],"style":{"bg":"#fafafa","padding":18,"radius":12,"border_width":1,"border_color":"#f4f4f5"}}},{"id":"intel","type":"paragraph","data":{"html":"Know someone we should interview next? Just reply to this email."}},{"id":"intem","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":17,"line_height":1.65,"text":"#18181b","muted":"#71717a","bg":"#fdf2f8","content_bg":"#ffffff","accent":"#db2777","link":"#be185d","button_bg":"#db2777","button_text":"#ffffff","border":"#fbcfe8","radius":12,"width":640,"spacing":16},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"''Playfair Display'', Georgia, serif","text":"#18181b","accent":"#db2777","accent_text":"#ffffff"}}', 0, 'Editorial', 1793000000004, 1793000000004);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_changelog', NULL, 'Product update / changelog', 'post', 'Release notes with a hero, “new / improved / fixed” changelog table, feature columns and a clear call to action.', '{"blocks":[{"id":"chan5","type":"section","data":{"blocks":[{"id":"chan1","type":"paragraph","data":{"html":"<b>RELEASE NOTES · VERSION 2.4</b>","align":"center"}},{"id":"chan2","type":"heading","data":{"level":1,"html":"The biggest update this year","align":"center"}},{"id":"chan3","type":"paragraph","data":{"html":"A one-sentence summary of the theme of this release and who it’s for.","align":"center"}},{"id":"chan4","type":"button","data":{"label":"See what’s new","url":"https://example.com","align":"center"}}],"style":{"bg":"#eef2ff","padding":32,"radius":14,"border_width":1,"border_color":"#c7d2fe"}}},{"id":"chan6","type":"heading","data":{"level":2,"html":"Highlights"}},{"id":"chanb","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"chan7","type":"heading","data":{"level":4,"html":"⚡ Feature one"}},{"id":"chan8","type":"paragraph","data":{"html":"What it does, the problem it solves, and how to find it."}}]},{"blocks":[{"id":"chan9","type":"heading","data":{"level":4,"html":"🎯 Feature two"}},{"id":"chana","type":"paragraph","data":{"html":"What it does, the problem it solves, and how to find it."}}]}]}},{"id":"chanc","type":"heading","data":{"level":2,"html":"Everything in this release"}},{"id":"chand","type":"table","data":{"rows":[["Type","Change"],["✨ New","Short description of a new capability"],["✨ New","Another new capability"],["🔧 Improved","What got faster, simpler or clearer"],["🐞 Fixed","The bug, in user terms"]],"header":true}},{"id":"chane","type":"quote","data":{"html":"“A short quote from a customer or beta tester about the update.”","cite":"Customer Name, Company","style":{"variant":"line","border_color":"#4f46e5"}}},{"id":"chanf","type":"heading","data":{"level":2,"html":"Coming next"}},{"id":"chang","type":"list","data":{"ordered":false,"items":["Something on the roadmap","Something you’re exploring — tell us if you want it"]}},{"id":"chanh","type":"button","data":{"label":"Try it now","url":"https://example.com","align":"center"}},{"id":"chani","type":"paragraph","data":{"html":"Questions or feedback? Reply to this email — it goes straight to the product team.","align":"center"}}]}', '{"email":{"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.6,"text":"#0b1220","muted":"#5b6475","bg":"#f1f5f9","content_bg":"#ffffff","accent":"#4f46e5","link":"#4338ca","button_bg":"#4f46e5","button_text":"#ffffff","border":"#e2e8f0","radius":12,"width":640,"spacing":16},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#0b1220","accent":"#4f46e5","accent_text":"#ffffff"}}', 0, 'Business', 1793000000005, 1793000000005);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_sponsor_dedicated', NULL, 'Dedicated sponsor issue', 'post', 'A fully sponsored send: transparent intro, hero sponsor placement, editorial value, secondary classifieds and a disclosure.', '{"blocks":[{"id":"spon1","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}} — today’s issue is made possible by <b>Sponsor Name</b>. We only partner with products we’d recommend anyway, and sponsorships keep {{publication.name}} free for everyone."}},{"id":"spon2","type":"ad","data":{"label":"Today’s sponsor","headline":"Sponsor headline: the benefit, not the feature","body":"Two or three sentences in the sponsor’s voice that explain the offer and who it’s for. Include the exclusive deal for our readers.","url":"https://example.com","cta":"Claim the offer"}},{"id":"spon3","type":"heading","data":{"level":2,"html":"Why we said yes"}},{"id":"spon4","type":"paragraph","data":{"html":"A short, honest paragraph on how you’ve used the product, what you like, and who it isn’t for."}},{"id":"spon8","type":"section","data":{"blocks":[{"id":"spon5","type":"heading","data":{"level":3,"html":"Exclusive for readers"}},{"id":"spon6","type":"paragraph","data":{"html":"Use code <b>READERS20</b> for 20% off your first three months."}},{"id":"spon7","type":"button","data":{"label":"Get the deal","url":"https://example.com","align":"left"}}],"style":{"bg":"#fff7ed","padding":22,"radius":12,"border_width":1,"border_color":"#fed7aa"}}},{"id":"spon9","type":"heading","data":{"level":2,"html":"This week’s story"}},{"id":"spona","type":"paragraph","data":{"html":"Your regular editorial content continues here so the issue still delivers value on its own."}},{"id":"sponb","type":"heading","data":{"level":3,"html":"Classifieds"}},{"id":"spone","type":"section","data":{"blocks":[{"id":"sponc","type":"paragraph","data":{"html":"<b><a href=\"https://example.com\">Secondary sponsor</a></b> — a one-line classified-style placement."}},{"id":"spond","type":"paragraph","data":{"html":"<b><a href=\"https://example.com\">Another sponsor</a></b> — a one-line classified-style placement."}}],"style":{"bg":"#fafafa","padding":18,"radius":10}}},{"id":"sponf","type":"paragraph","data":{"html":"<i>Want to reach {{publication.name}} readers? <a href=\"{{publication.url}}/sponsor\">Advertise with us</a>.</i>"}},{"id":"spong","type":"recommendations","data":{"title":"Newsletters our readers love","limit":3}},{"id":"sponh","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":17,"line_height":1.6,"text":"#1f2937","muted":"#6b7280","bg":"#fff7ed","content_bg":"#ffffff","accent":"#ea580c","link":"#c2410c","button_bg":"#ea580c","button_text":"#ffffff","border":"#fed7aa","radius":12,"width":640,"spacing":16},"web":{"font":"''DM Sans'', sans-serif","heading_font":"''DM Sans'', sans-serif","text":"#1f2937","accent":"#ea580c","accent_text":"#ffffff"}}', 0, 'Business', 1793000000006, 1793000000006);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_podcast_notes', NULL, 'Podcast episode notes', 'post', 'Show notes with the episode player, guest intro, timestamps, quotes, mentioned links and a sponsor read.', '{"blocks":[{"id":"podc4","type":"section","data":{"blocks":[{"id":"podc1","type":"paragraph","data":{"html":"<b>🎙 NEW EPISODE · #42</b>"}},{"id":"podc2","type":"heading","data":{"level":2,"html":"Episode title that promises a payoff"}},{"id":"podc3","type":"paragraph","data":{"html":"With <b>Guest Name</b>, Role at Company · 48 min"}}],"style":{"bg":"#f5f3ff","padding":22,"radius":14}}},{"id":"podc5","type":"paragraph","data":{"html":"Pick the episode in the block below to embed the player — readers can listen right from the web version."}},{"id":"podc6","type":"podcast","data":{"episode_id":""}},{"id":"podc7","type":"button","data":{"label":"▶ Listen now","url":"https://example.com","align":"center"}},{"id":"podc8","type":"heading","data":{"level":3,"html":"In this episode"}},{"id":"podc9","type":"paragraph","data":{"html":"Two sentences on what the conversation covers and why it matters to listeners."}},{"id":"podca","type":"heading","data":{"level":3,"html":"Timestamps"}},{"id":"podcb","type":"list","data":{"ordered":false,"items":["<b>00:00</b> — Intro","<b>03:15</b> — How Guest got started","<b>14:40</b> — The big idea","<b>31:05</b> — Listener questions","<b>44:20</b> — Lightning round"]}},{"id":"podcc","type":"quote","data":{"html":"The best line from the episode, worth sharing on its own.","cite":"Guest Name","style":{"variant":"line","border_color":"#7c3aed"}}},{"id":"podcd","type":"ad","data":{"label":"This episode is supported by","headline":"Podcast sponsor headline","body":"The host-read sponsor message, adapted for email. Include the listener code.","url":"https://example.com","cta":"Get the listener offer"}},{"id":"podce","type":"heading","data":{"level":3,"html":"Mentioned in the show"}},{"id":"podcf","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">Book, article or tool mentioned</a>","<a href=\"https://example.com\">Another resource</a>"]}},{"id":"podcg","type":"paragraph","data":{"html":"Enjoying the show? Leave a review and share this episode with a friend."}},{"id":"podch","type":"referral","data":{"title":"Share the show, earn rewards"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.6,"text":"#18181b","muted":"#71717a","bg":"#1f1b3a","content_bg":"#ffffff","accent":"#7c3aed","link":"#6d28d9","button_bg":"#7c3aed","button_text":"#ffffff","border":"#ede9fe","radius":14,"width":640,"spacing":16},"web":{"font":"''DM Sans'', sans-serif","heading_font":"''DM Sans'', sans-serif","text":"#111827","accent":"#7c3aed","accent_text":"#ffffff"}}', 0, 'Media & events', 1793000000007, 1793000000007);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_event_announcement', NULL, 'Event announcement', 'post', 'Bold invitation with date/location card, agenda table, speakers grid, registration block and FAQ.', '{"blocks":[{"id":"even5","type":"section","data":{"blocks":[{"id":"even1","type":"paragraph","data":{"html":"<b>YOU’RE INVITED</b>","align":"center"}},{"id":"even2","type":"heading","data":{"level":1,"html":"Event name: the promise in five words","align":"center"}},{"id":"even3","type":"paragraph","data":{"html":"📅 Thursday, March 12 · 6:00–8:30 PM<br>📍 Venue name, City — or online","align":"center"}},{"id":"even4","type":"button","data":{"label":"Save my seat","url":"https://example.com","align":"center"}}],"style":{"bg":"#cffafe","padding":36,"radius":16}}},{"id":"even6","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}}, we’re hosting our first live event for readers and we’d love for you to be there. Here’s why it’s worth an evening:"}},{"id":"even7","type":"list","data":{"ordered":false,"items":["Meet other readers who care about the same things you do","Hear from three speakers we’ve been wanting to feature for years","Leave with one practical idea you can use the next morning"]}},{"id":"even8","type":"heading","data":{"level":2,"html":"Agenda"}},{"id":"even9","type":"table","data":{"rows":[["Time","Session"],["6:00 PM","Doors open, drinks & introductions"],["6:30 PM","Keynote: Speaker Name"],["7:15 PM","Panel discussion + audience Q&A"],["8:00 PM","Networking"]],"header":true}},{"id":"evena","type":"heading","data":{"level":2,"html":"Speakers"}},{"id":"evenh","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"evenb","type":"heading","data":{"level":4,"html":"Speaker One"}},{"id":"evenc","type":"paragraph","data":{"html":"Role, Company. One line on what they’ll talk about."}}]},{"blocks":[{"id":"evend","type":"heading","data":{"level":4,"html":"Speaker Two"}},{"id":"evene","type":"paragraph","data":{"html":"Role, Company. One line on what they’ll talk about."}}]},{"blocks":[{"id":"evenf","type":"heading","data":{"level":4,"html":"Speaker Three"}},{"id":"eveng","type":"paragraph","data":{"html":"Role, Company. One line on what they’ll talk about."}}]}]}},{"id":"eveni","type":"heading","data":{"level":2,"html":"Register"}},{"id":"evenj","type":"paragraph","data":{"html":"Choose your event below to show the live registration card with date and ticket button."}},{"id":"evenk","type":"event","data":{"event_id":""}},{"id":"evenl","type":"heading","data":{"level":3,"html":"FAQ"}},{"id":"evenm","type":"paragraph","data":{"html":"<b>Is there a recording?</b> Yes — registered attendees get the replay."}},{"id":"evenn","type":"paragraph","data":{"html":"<b>Can I bring a friend?</b> Absolutely. Forward this email."}},{"id":"eveno","type":"button","data":{"label":"Register now","url":"https://example.com","align":"center"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.6,"text":"#0f172a","muted":"#64748b","bg":"#ecfeff","content_bg":"#ffffff","accent":"#0891b2","link":"#0e7490","button_bg":"#0891b2","button_text":"#ffffff","border":"#cffafe","radius":14,"width":640,"spacing":16},"web":{"font":"''DM Sans'', sans-serif","heading_font":"''DM Sans'', sans-serif","text":"#0f172a","accent":"#0891b2","accent_text":"#ffffff"}}', 0, 'Media & events', 1793000000008, 1793000000008);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_flash_sale', NULL, 'Deal / flash sale', 'post', 'High-energy promo with discount hero, code box, product spotlight columns, urgency and FAQ.', '{"blocks":[{"id":"flas5","type":"section","data":{"blocks":[{"id":"flas1","type":"paragraph","data":{"html":"<b>48 HOURS ONLY</b>","align":"center"}},{"id":"flas2","type":"heading","data":{"level":1,"html":"40% off everything","align":"center"}},{"id":"flas3","type":"paragraph","data":{"html":"Our biggest sale of the year ends Sunday at midnight.","align":"center"}},{"id":"flas4","type":"button","data":{"label":"Shop the sale →","url":"https://example.com","align":"center","bg":"#111827","color":"#ffffff"}}],"style":{"bg":"#fde047","color":"#111827","padding":36,"radius":16}}},{"id":"flas6","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}} — as a subscriber you get early access. Use the code below at checkout:"}},{"id":"flasa","type":"section","data":{"blocks":[{"id":"flas7","type":"paragraph","data":{"html":"YOUR CODE","align":"center"}},{"id":"flas8","type":"heading","data":{"level":2,"html":"SUBSCRIBER40","align":"center"}},{"id":"flas9","type":"paragraph","data":{"html":"Applies to all products · one use per customer","align":"center"}}],"style":{"bg":"#fff1f2","padding":20,"radius":12,"border_width":2,"border_style":"dashed","border_color":"#e11d48"}}},{"id":"flasb","type":"heading","data":{"level":2,"html":"Readers’ favorites"}},{"id":"flasi","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"flasc","type":"heading","data":{"level":4,"html":"Product one"}},{"id":"flasd","type":"paragraph","data":{"html":"<s>$49</s> <b>$29</b> — one line on why people love it."}},{"id":"flase","type":"button","data":{"label":"Get it","url":"https://example.com","align":"left"}}]},{"blocks":[{"id":"flasf","type":"heading","data":{"level":4,"html":"Product two"}},{"id":"flasg","type":"paragraph","data":{"html":"<s>$99</s> <b>$59</b> — one line on why people love it."}},{"id":"flash","type":"button","data":{"label":"Get it","url":"https://example.com","align":"left"}}]}]}},{"id":"flasj","type":"heading","data":{"level":3,"html":"Why we’re doing this"}},{"id":"flask","type":"paragraph","data":{"html":"A short, human reason for the sale — an anniversary, a milestone, clearing space for something new."}},{"id":"flasl","type":"heading","data":{"level":3,"html":"FAQ"}},{"id":"flasm","type":"paragraph","data":{"html":"<b>When does it end?</b> Sunday at 11:59 PM in your time zone."}},{"id":"flasn","type":"paragraph","data":{"html":"<b>Does it stack with other offers?</b> No, but it’s the best price we’ll offer this year."}},{"id":"flaso","type":"button","data":{"label":"Use my 40% off","url":"https://example.com","align":"center"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.55,"text":"#111827","muted":"#6b7280","bg":"#fef9c3","content_bg":"#ffffff","accent":"#e11d48","link":"#be123c","button_bg":"#e11d48","button_text":"#ffffff","border":"#fde68a","radius":14,"width":620,"spacing":16},"web":{"font":"''DM Sans'', sans-serif","heading_font":"''DM Sans'', sans-serif","text":"#111827","accent":"#e11d48","accent_text":"#ffffff"}}', 0, 'Business', 1793000000009, 1793000000009);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_tutorial', NULL, 'Tutorial / how-to', 'post', 'Step-by-step guide with outcome summary, prerequisites checklist, numbered steps, code sample, pro tip and next steps.', '{"blocks":[{"id":"tuto3","type":"section","data":{"blocks":[{"id":"tuto1","type":"heading","data":{"level":3,"html":"What you’ll build"}},{"id":"tuto2","type":"paragraph","data":{"html":"By the end of this guide you’ll be able to <b>do the specific thing</b>. It takes about 15 minutes."}}],"style":{"bg":"#f0fdf4","padding":20,"radius":10,"border_width":1,"border_color":"#bbf7d0"}}},{"id":"tuto4","type":"heading","data":{"level":2,"html":"Before you start"}},{"id":"tuto5","type":"checklist","data":{"items":[{"html":"An account on the tool we’re using","checked":false},{"html":"Ten minutes of focused time","checked":false},{"html":"Basic familiarity with the concept","checked":false}]}},{"id":"tuto6","type":"heading","data":{"level":2,"html":"Step 1 — Set things up"}},{"id":"tuto7","type":"paragraph","data":{"html":"Explain the first action in plain language. Say what the reader should see when it worked."}},{"id":"tuto8","type":"heading","data":{"level":2,"html":"Step 2 — Do the main thing"}},{"id":"tuto9","type":"paragraph","data":{"html":"Break the core work into the smallest steps that still make sense on their own."}},{"id":"tutoa","type":"code","data":{"lang":"bash","code":"# paste the exact command or snippet here\nnpm install example-package\nexample init --name my-project"}},{"id":"tutoc","type":"section","data":{"blocks":[{"id":"tutob","type":"paragraph","data":{"html":"💡 <b>Pro tip:</b> the shortcut or gotcha that took you hours to discover."}}],"style":{"bg":"#fefce8","padding":16,"radius":10,"border_width":1,"border_color":"#fde68a"}}},{"id":"tutod","type":"heading","data":{"level":2,"html":"Step 3 — Check your work"}},{"id":"tutoe","type":"paragraph","data":{"html":"Show what “done” looks like and how to troubleshoot the two most common problems."}},{"id":"tutof","type":"heading","data":{"level":2,"html":"Next steps"}},{"id":"tutog","type":"list","data":{"ordered":true,"items":["Try the variation for advanced users","Read the follow-up guide","Share what you built — reply with a link"]}},{"id":"tutoh","type":"paywall","data":{}},{"id":"tutoi","type":"heading","data":{"level":2,"html":"Bonus for members: the template files"}},{"id":"tutoj","type":"paragraph","data":{"html":"Premium readers get the downloadable starter files and a video walkthrough."}},{"id":"tutok","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.65,"text":"#1e293b","muted":"#64748b","bg":"#f0fdf4","content_bg":"#ffffff","accent":"#16a34a","link":"#15803d","button_bg":"#16a34a","button_text":"#ffffff","border":"#dcfce7","radius":10,"width":660,"spacing":16},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#1e293b","accent":"#16a34a","accent_text":"#ffffff"}}', 0, 'Education', 1793000000010, 1793000000010);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_founder_letter', NULL, 'Founder letter', 'post', 'A personal, letter-style note from the founder: candid update, lessons, what’s next and a warm sign-off.', '{"blocks":[{"id":"foun1","type":"paragraph","data":{"html":"Dear {{subscriber.first_name|friend}},"}},{"id":"foun2","type":"paragraph","data":{"html":"I don’t write letters like this often, so I’ll get straight to it: here is where we are, what we’ve learned, and what comes next."}},{"id":"foun3","type":"heading","data":{"level":3,"html":"Where we are"}},{"id":"foun4","type":"paragraph","data":{"html":"A candid update. Share the real numbers if you can, the wins, and at least one thing that didn’t go to plan."}},{"id":"foun5","type":"heading","data":{"level":3,"html":"What I got wrong"}},{"id":"foun6","type":"paragraph","data":{"html":"Readers trust founders who admit mistakes. What did you believe a year ago that turned out to be wrong?"}},{"id":"foun7","type":"quote","data":{"html":"One sentence you want people to remember from this letter.","cite":"","style":{"variant":"line","border_color":"#b45309","italic":true}}},{"id":"foun8","type":"heading","data":{"level":3,"html":"What comes next"}},{"id":"foun9","type":"paragraph","data":{"html":"The plan for the next season, and the specific way readers can help — feedback, a referral, an upgrade."}},{"id":"founa","type":"paragraph","data":{"html":"Thank you for reading, for replying, and for sticking with us."}},{"id":"founb","type":"paragraph","data":{"html":"Warmly,<br><b>Founder Name</b><br><i>Founder, {{publication.name}}</i>"}},{"id":"founc","type":"divider","data":{"style":"space"}},{"id":"found","type":"paragraph","data":{"html":"<i>P.S. — I read every reply. Tell me one thing we should start, stop or keep doing.</i>"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":18,"line_height":1.75,"text":"#292524","muted":"#78716c","bg":"#f5f5f4","content_bg":"#fffefb","accent":"#b45309","link":"#92400e","button_bg":"#292524","button_text":"#ffffff","border":"#e7e5e4","radius":4,"width":600,"spacing":20},"web":{"font":"Merriweather, Georgia, serif","heading_font":"Merriweather, Georgia, serif","text":"#292524","accent":"#b45309","accent_text":"#ffffff"}}', 0, 'Editorial', 1793000000011, 1793000000011);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_by_the_numbers', NULL, 'By the numbers', 'post', 'Data-driven issue: headline stats cards, a chart-ready table, analysis, “number of the week” and a reader poll.', '{"blocks":[{"id":"byth1","type":"paragraph","data":{"html":"This week in numbers, {{subscriber.first_name|there}}: what moved, what didn’t, and what it means."}},{"id":"bythb","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"byth4","type":"section","data":{"blocks":[{"id":"byth2","type":"heading","data":{"level":1,"html":"$4.2B","align":"center"}},{"id":"byth3","type":"paragraph","data":{"html":"raised by startups in the sector this quarter","align":"center"}}],"style":{"bg":"#ecfeff","padding":16,"radius":12}}}]},{"blocks":[{"id":"byth7","type":"section","data":{"blocks":[{"id":"byth5","type":"heading","data":{"level":1,"html":"+38%","align":"center"}},{"id":"byth6","type":"paragraph","data":{"html":"year-over-year growth in the key metric","align":"center"}}],"style":{"bg":"#f0fdf4","padding":16,"radius":12}}}]},{"blocks":[{"id":"bytha","type":"section","data":{"blocks":[{"id":"byth8","type":"heading","data":{"level":1,"html":"1 in 4","align":"center"}},{"id":"byth9","type":"paragraph","data":{"html":"people say they’ve tried it at least once","align":"center"}}],"style":{"bg":"#fef2f2","padding":16,"radius":12}}}]}]}},{"id":"bythc","type":"heading","data":{"level":2,"html":"The data"}},{"id":"bythd","type":"table","data":{"rows":[["Metric","Last year","This year","Change"],["Metric one","1,204","1,662","+38%"],["Metric two","$18.40","$21.10","+15%"],["Metric three","42%","39%","−3 pts"]],"header":true}},{"id":"bythe","type":"paragraph","data":{"html":"<i>Source: name the source and link to the methodology.</i>"}},{"id":"bythf","type":"heading","data":{"level":2,"html":"What it means"}},{"id":"bythg","type":"paragraph","data":{"html":"Two or three paragraphs of analysis. Separate signal from noise and name the one trend you’d bet on."}},{"id":"bythk","type":"section","data":{"blocks":[{"id":"bythh","type":"paragraph","data":{"html":"<b>NUMBER OF THE WEEK</b>"}},{"id":"bythi","type":"heading","data":{"level":1,"html":"17"}},{"id":"bythj","type":"paragraph","data":{"html":"The story behind one surprising number, told in three sentences."}}],"style":{"bg":"#fef9c3","padding":24,"radius":12,"border_width":1,"border_color":"#fde68a"}}},{"id":"bythl","type":"heading","data":{"level":3,"html":"Your turn"}},{"id":"bythm","type":"paragraph","data":{"html":"Which number surprised you most? Vote below."}},{"id":"bythn","type":"poll","data":{"poll_id":""}},{"id":"bytho","type":"ad","data":{"label":"Data partner","headline":"Your sponsor’s headline goes here","body":"Two sentences on what the sponsor does and why it is useful to this audience. Keep it honest and specific.","url":"https://example.com","cta":"Learn more"}},{"id":"bythp","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.6,"text":"#0f172a","muted":"#64748b","bg":"#eef2ff","content_bg":"#ffffff","accent":"#0d9488","link":"#0f766e","button_bg":"#0f172a","button_text":"#ffffff","border":"#e2e8f0","radius":12,"width":660,"spacing":16},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#0f172a","accent":"#0d9488","accent_text":"#ffffff"}}', 0, 'Data', 1793000000012, 1793000000012);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_welcome_issue', NULL, 'Welcome issue', 'post', 'Issue #1 for a new newsletter: the mission, what readers will get, the schedule, best posts and how to get involved.', '{"blocks":[{"id":"welc3","type":"section","data":{"blocks":[{"id":"welc1","type":"heading","data":{"level":1,"html":"Welcome to {{publication.name}} 👋","align":"center"}},{"id":"welc2","type":"paragraph","data":{"html":"You’re one of the very first readers — thank you for being here.","align":"center"}}],"style":{"bg":"#fef3c7","padding":32,"radius":16}}},{"id":"welc4","type":"heading","data":{"level":2,"html":"Why this newsletter exists"}},{"id":"welc5","type":"paragraph","data":{"html":"Explain the gap you saw, the reader you’re writing for, and the promise you’re making to them."}},{"id":"welc6","type":"heading","data":{"level":2,"html":"What you’ll get"}},{"id":"welcd","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"welc7","type":"heading","data":{"level":4,"html":"📬 Every Tuesday"}},{"id":"welc8","type":"paragraph","data":{"html":"The main issue: one big idea, explained clearly."}}]},{"blocks":[{"id":"welc9","type":"heading","data":{"level":4,"html":"🔗 Every Friday"}},{"id":"welca","type":"paragraph","data":{"html":"A short list of the best links of the week."}}]},{"blocks":[{"id":"welcb","type":"heading","data":{"level":4,"html":"⭐ Members"}},{"id":"welcc","type":"paragraph","data":{"html":"Deep dives, templates and the full archive."}}]}]}},{"id":"welce","type":"heading","data":{"level":2,"html":"Start here"}},{"id":"welcf","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\">Your best or most popular piece</a>","<a href=\"https://example.com\">The piece that explains your worldview</a>","<a href=\"{{publication.url}}\">Browse the archive</a>"]}},{"id":"welcg","type":"heading","data":{"level":2,"html":"Get involved"}},{"id":"welch","type":"paragraph","data":{"html":"Reply to this email and tell me what you’re working on — I read every message and often feature reader questions."}},{"id":"welci","type":"referral","data":{"title":"Invite a friend, earn rewards"}},{"id":"welcj","type":"paragraph","data":{"html":"See you next week,<br>{{publication.name}}"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":17,"line_height":1.65,"text":"#1f2937","muted":"#6b7280","bg":"#fffbeb","content_bg":"#ffffff","accent":"#f59e0b","link":"#b45309","button_bg":"#f59e0b","button_text":"#111827","border":"#fde68a","radius":14,"width":620,"spacing":16},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#1f2937","accent":"#f59e0b","accent_text":"#111827"}}', 0, 'Welcome', 1793000000013, 1793000000013);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_year_in_review', NULL, 'Year in review', 'post', 'Celebrate the year: stats highlights, top posts, milestones timeline, reader favorites, thanks and what’s next.', '{"blocks":[{"id":"year4","type":"section","data":{"blocks":[{"id":"year1","type":"paragraph","data":{"html":"<b>✦ THE YEAR IN REVIEW ✦</b>","align":"center"}},{"id":"year2","type":"heading","data":{"level":1,"html":"What a year it’s been","align":"center"}},{"id":"year3","type":"paragraph","data":{"html":"Thank you for reading {{publication.name}}. Here’s the year, by the numbers and the stories.","align":"center"}}],"style":{"bg":"#e0e7ff","padding":36,"radius":16}}},{"id":"yeare","type":"columns","data":{"valign":"top","columns":[{"blocks":[{"id":"year7","type":"section","data":{"blocks":[{"id":"year5","type":"heading","data":{"level":2,"html":"52","align":"center"}},{"id":"year6","type":"paragraph","data":{"html":"issues sent","align":"center"}}],"style":{"bg":"#eef2ff","padding":14,"radius":12}}}]},{"blocks":[{"id":"yeara","type":"section","data":{"blocks":[{"id":"year8","type":"heading","data":{"level":2,"html":"12k","align":"center"}},{"id":"year9","type":"paragraph","data":{"html":"new readers","align":"center"}}],"style":{"bg":"#fef3c7","padding":14,"radius":12}}}]},{"blocks":[{"id":"yeard","type":"section","data":{"blocks":[{"id":"yearb","type":"heading","data":{"level":2,"html":"68%","align":"center"}},{"id":"yearc","type":"paragraph","data":{"html":"average open rate","align":"center"}}],"style":{"bg":"#ecfdf5","padding":14,"radius":12}}}]}]}},{"id":"yearf","type":"heading","data":{"level":2,"html":"Your five favorite posts"}},{"id":"yearg","type":"list","data":{"ordered":true,"items":["<a href=\"https://example.com\"><b>Most-read post</b></a> — why it resonated","<a href=\"https://example.com\"><b>Second post</b></a>","<a href=\"https://example.com\"><b>Third post</b></a>","<a href=\"https://example.com\"><b>Fourth post</b></a>","<a href=\"https://example.com\"><b>Fifth post</b></a>"]}},{"id":"yearh","type":"heading","data":{"level":2,"html":"Milestones"}},{"id":"yeari","type":"table","data":{"rows":[["Month","Milestone"],["February","Launched the podcast"],["June","Passed 10,000 subscribers"],["September","First live reader meetup"],["December","You’re reading this"]],"header":true}},{"id":"yearj","type":"heading","data":{"level":2,"html":"A reader favorite"}},{"id":"yeark","type":"quote","data":{"html":"Share a reply or comment from a reader that made your year.","cite":"Reader name","style":{"variant":"box","border_color":"#f59e0b","bg":"#fffbeb"}}},{"id":"yearl","type":"heading","data":{"level":2,"html":"What’s coming next year"}},{"id":"yearm","type":"list","data":{"ordered":false,"items":["A big new format or series","More of what you asked for","One surprise we can’t talk about yet"]}},{"id":"yearn","type":"heading","data":{"level":3,"html":"Help us plan"}},{"id":"yearo","type":"poll","data":{"poll_id":""}},{"id":"yearp","type":"referral","data":{"title":"Start the new year by sharing {{publication.name}}"}},{"id":"yearq","type":"recommendations","data":{"title":"Newsletters we loved this year","limit":3}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":17,"line_height":1.65,"text":"#1e1b4b","muted":"#6366f1","bg":"#1e1b4b","content_bg":"#ffffff","accent":"#f59e0b","link":"#4338ca","button_bg":"#1e1b4b","button_text":"#ffffff","border":"#e0e7ff","radius":14,"width":640,"spacing":18},"web":{"font":"Lora, Georgia, serif","heading_font":"''DM Sans'', sans-serif","text":"#1e1b4b","accent":"#f59e0b","accent_text":"#1e1b4b"}}', 0, 'Seasonal', 1793000000014, 1793000000014);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_mailbag', NULL, 'Reader mailbag / AMA', 'post', 'Answer reader questions: intro, question cards, quick-fire answers, a poll for next time and a call for questions.', '{"blocks":[{"id":"mail1","type":"paragraph","data":{"html":"You asked, I answered. This month’s mailbag covers the questions that came up most — plus a few favorites."}},{"id":"mail4","type":"section","data":{"blocks":[{"id":"mail2","type":"paragraph","data":{"html":"<b>📮 “Paste the reader’s question here, lightly edited for length?”</b>"}},{"id":"mail3","type":"paragraph","data":{"html":"— Reader name, City"}}],"style":{"bg":"#f0f9ff","padding":18,"radius":14}}},{"id":"mail5","type":"paragraph","data":{"html":"Your answer. Be specific and generous — the best mailbag answers are useful to everyone, not just the person who asked."}},{"id":"mail8","type":"section","data":{"blocks":[{"id":"mail6","type":"paragraph","data":{"html":"<b>📮 “A second question from a different reader?”</b>"}},{"id":"mail7","type":"paragraph","data":{"html":"— Reader name"}}],"style":{"bg":"#f0f9ff","padding":18,"radius":14}}},{"id":"mail9","type":"paragraph","data":{"html":"Your answer."}},{"id":"mailc","type":"section","data":{"blocks":[{"id":"maila","type":"paragraph","data":{"html":"<b>📮 “A third, maybe more personal question?”</b>"}},{"id":"mailb","type":"paragraph","data":{"html":"— Reader name"}}],"style":{"bg":"#f0f9ff","padding":18,"radius":14}}},{"id":"maild","type":"paragraph","data":{"html":"Your answer."}},{"id":"maile","type":"heading","data":{"level":3,"html":"Lightning round"}},{"id":"mailf","type":"list","data":{"ordered":false,"items":["<b>Favorite book this year?</b> Short answer.","<b>Coffee or tea?</b> Short answer.","<b>Best advice you ever got?</b> Short answer."]}},{"id":"mailg","type":"heading","data":{"level":3,"html":"What should the next mailbag cover?"}},{"id":"mailh","type":"poll","data":{"poll_id":""}},{"id":"maili","type":"button","data":{"label":"Ask a question","url":"mailto:hello@example.com","align":"center"}},{"id":"mailj","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"''Trebuchet MS'', Tahoma, sans-serif","heading_font":"''Trebuchet MS'', Tahoma, sans-serif","font_size":16,"line_height":1.6,"text":"#1f2937","muted":"#6b7280","bg":"#f0f9ff","content_bg":"#ffffff","accent":"#0284c7","link":"#0369a1","button_bg":"#0284c7","button_text":"#ffffff","border":"#e0f2fe","radius":14,"width":620,"spacing":16},"web":{"font":"''DM Sans'', sans-serif","heading_font":"''DM Sans'', sans-serif","text":"#1f2937","accent":"#0284c7","accent_text":"#ffffff"}}', 0, 'Editorial', 1793000000015, 1793000000015);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_jobs', NULL, 'Jobs & opportunities', 'post', 'Curated job board issue: featured (paid) role, listings by category, quick-apply buttons and a “post a job” CTA.', '{"blocks":[{"id":"jobs1","type":"paragraph","data":{"html":"The best open roles we found this week, {{subscriber.first_name|there}} — hand-checked, salary listed when available."}},{"id":"jobs7","type":"section","data":{"blocks":[{"id":"jobs2","type":"paragraph","data":{"html":"<b>⭐ FEATURED ROLE</b>"}},{"id":"jobs3","type":"heading","data":{"level":3,"html":"Senior Role Title · Company"}},{"id":"jobs4","type":"paragraph","data":{"html":"Remote (US/EU) · $150k–$180k · Full-time"}},{"id":"jobs5","type":"paragraph","data":{"html":"Two sentences on the team, the mission and why this role is special."}},{"id":"jobs6","type":"button","data":{"label":"Apply now","url":"https://example.com","align":"left"}}],"style":{"bg":"#f5f3ff","padding":22,"radius":12,"border_width":1,"border_color":"#ddd6fe"}}},{"id":"jobs8","type":"heading","data":{"level":2,"html":"Engineering"}},{"id":"jobs9","type":"table","data":{"rows":[["Role","Company","Location",""],["Role title","Company","Remote","<a href=\"https://example.com\">Apply →</a>"],["Role title","Company","NYC","<a href=\"https://example.com\">Apply →</a>"]],"header":true}},{"id":"jobsa","type":"heading","data":{"level":2,"html":"Design & product"}},{"id":"jobsb","type":"table","data":{"rows":[["Role","Company","Location",""],["Role title","Company","Remote","<a href=\"https://example.com\">Apply →</a>"],["Role title","Company","London","<a href=\"https://example.com\">Apply →</a>"]],"header":true}},{"id":"jobsc","type":"heading","data":{"level":2,"html":"Marketing & growth"}},{"id":"jobsd","type":"table","data":{"rows":[["Role","Company","Location",""],["Role title","Company","Remote","<a href=\"https://example.com\">Apply →</a>"]],"header":true}},{"id":"jobsh","type":"section","data":{"blocks":[{"id":"jobse","type":"heading","data":{"level":3,"html":"Hiring?"}},{"id":"jobsf","type":"paragraph","data":{"html":"Reach thousands of qualified readers. Featured listings include a dedicated spot at the top of the issue."}},{"id":"jobsg","type":"button","data":{"label":"Post a job","url":"https://example.com","align":"left","bg":"#111827","color":"#ffffff"}}],"style":{"bg":"#f9fafb","padding":20,"radius":12}}},{"id":"jobsi","type":"referral","data":{"title":"Know someone job hunting? Forward this"}}]}', '{"email":{"font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","heading_font":"-apple-system, BlinkMacSystemFont, ''Segoe UI'', Helvetica, Arial, sans-serif","font_size":15,"line_height":1.55,"text":"#111827","muted":"#6b7280","bg":"#f3f4f6","content_bg":"#ffffff","accent":"#7c3aed","link":"#6d28d9","button_bg":"#7c3aed","button_text":"#ffffff","border":"#e5e7eb","radius":10,"width":640,"spacing":14},"web":{"font":"Inter, -apple-system, sans-serif","heading_font":"Inter, -apple-system, sans-serif","text":"#111827","accent":"#7c3aed","accent_text":"#ffffff"}}', 0, 'Business', 1793000000016, 1793000000016);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_premium_deep_dive', NULL, 'Premium deep dive', 'post', 'Paid-subscriber analysis: free executive summary, paywall, then the full research with charts tables and sources.', '{"blocks":[{"id":"prem3","type":"section","data":{"blocks":[{"id":"prem1","type":"paragraph","data":{"html":"<b>EXECUTIVE SUMMARY</b>"}},{"id":"prem2","type":"list","data":{"ordered":false,"items":["The core finding in one sentence","The second finding","What we recommend"]}}],"style":{"bg":"#ecfdf5","padding":20,"radius":8,"border_width":1,"border_color":"#a7f3d0"}}},{"id":"prem4","type":"paragraph","data":{"html":"Set up the question this deep dive answers and why it matters now. Free readers see this introduction; members get the full analysis below."}},{"id":"prem5","type":"toc","data":{}},{"id":"prem6","type":"paywall","data":{}},{"id":"prem7","type":"heading","data":{"level":2,"html":"1. Background"}},{"id":"prem8","type":"paragraph","data":{"html":"The context a smart newcomer needs. Define terms and link to primary sources."}},{"id":"prem9","type":"heading","data":{"level":2,"html":"2. The analysis"}},{"id":"prema","type":"paragraph","data":{"html":"The heart of the piece. Walk through the evidence step by step."}},{"id":"premb","type":"table","data":{"rows":[["Option","Pros","Cons","Verdict"],["Option A","Cheap, fast","Hard to scale","✅ Start here"],["Option B","Scales well","Expensive","⚠️ Later"],["Option C","Flexible","Complex","❌ Avoid"]],"header":true}},{"id":"premc","type":"heading","data":{"level":2,"html":"3. What we’d do"}},{"id":"premd","type":"paragraph","data":{"html":"A concrete recommendation with the reasoning laid bare."}},{"id":"preme","type":"heading","data":{"level":2,"html":"Sources"}},{"id":"premf","type":"list","data":{"ordered":true,"items":["<a href=\"https://example.com\">Source one</a>","<a href=\"https://example.com\">Source two</a>"]}},{"id":"premg","type":"paragraph","data":{"html":"<i>Questions about this analysis? Members can reply directly — I answer every one.</i>"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":18,"line_height":1.7,"text":"#111827","muted":"#6b7280","bg":"#f3f4f6","content_bg":"#ffffff","accent":"#047857","link":"#047857","button_bg":"#047857","button_text":"#ffffff","border":"#e5e7eb","radius":6,"width":660,"spacing":18},"web":{"font":"Merriweather, Georgia, serif","heading_font":"Inter, -apple-system, sans-serif","text":"#111827","accent":"#047857","accent_text":"#ffffff"}}', 0, 'Editorial', 1793000000017, 1793000000017);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_book_notes', NULL, 'Book notes / review', 'post', 'Book review with at-a-glance card, rating, key ideas, favorite quotes, who should read it and a reader poll.', '{"blocks":[{"id":"book4","type":"section","data":{"blocks":[{"id":"book1","type":"heading","data":{"level":2,"html":"Book Title"}},{"id":"book2","type":"paragraph","data":{"html":"<i>by Author Name</i> · 320 pages · Genre"}},{"id":"book3","type":"paragraph","data":{"html":"<b>Rating:</b> ★★★★☆ · <b>Read it if:</b> you want the one-line pitch."}}],"style":{"bg":"#f6efe3","padding":22,"radius":8,"border_width":1,"border_color":"#e6dccb"}}},{"id":"book5","type":"heading","data":{"level":3,"html":"The book in three sentences"}},{"id":"book6","type":"paragraph","data":{"html":"Summarize the whole argument as if explaining it to a friend over coffee."}},{"id":"book7","type":"heading","data":{"level":3,"html":"Big ideas"}},{"id":"book8","type":"list","data":{"ordered":true,"items":["<b>Idea one.</b> One paragraph explaining it and why it matters.","<b>Idea two.</b> One paragraph.","<b>Idea three.</b> One paragraph."]}},{"id":"book9","type":"heading","data":{"level":3,"html":"Favorite passages"}},{"id":"booka","type":"quote","data":{"html":"A short quote from the book (keep it brief and attributed).","cite":"Author Name, Book Title","style":{"variant":"line","border_color":"#7c2d12","italic":true}}},{"id":"bookb","type":"heading","data":{"level":3,"html":"Who should (and shouldn’t) read it"}},{"id":"bookc","type":"paragraph","data":{"html":"Be honest about the audience and the weak chapters."}},{"id":"bookd","type":"button","data":{"label":"Get the book","url":"https://example.com","align":"center"}},{"id":"booke","type":"heading","data":{"level":3,"html":"What should I read next?"}},{"id":"bookf","type":"poll","data":{"poll_id":""}},{"id":"bookg","type":"referral","data":{"title":"Share {{publication.name}}, earn rewards"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":18,"line_height":1.7,"text":"#2b2118","muted":"#8a7a66","bg":"#efe8dc","content_bg":"#fffaf2","accent":"#7c2d12","link":"#7c2d12","button_bg":"#7c2d12","button_text":"#fffaf2","border":"#e6dccb","radius":6,"width":620,"spacing":18},"web":{"font":"Lora, Georgia, serif","heading_font":"''Playfair Display'', Georgia, serif","text":"#2b2118","accent":"#7c2d12","accent_text":"#ffffff"}}', 0, 'Curation', 1793000000018, 1793000000018);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_welcome_warm', NULL, 'Warm personal welcome', 'welcome', 'A short, personal welcome from the writer that sets expectations and invites a reply — great for deliverability.', '{"blocks":[{"id":"welc1","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}},"}},{"id":"welc2","type":"paragraph","data":{"html":"Welcome to <b>{{publication.name}}</b> — I’m really glad you’re here."}},{"id":"welc3","type":"paragraph","data":{"html":"Here’s what to expect: one thoughtful email every week, no spam, and easy unsubscribe any time."}},{"id":"welc4","type":"paragraph","data":{"html":"One small favor: <b>hit reply and tell me what brought you here</b>. It helps me write better issues, and it tells your inbox you actually want to hear from me."}},{"id":"welc5","type":"paragraph","data":{"html":"Talk soon,<br>{{publication.name}}"}},{"id":"welc6","type":"paragraph","data":{"html":"<i>P.S. Can’t find my emails? Drag this one to your Primary tab.</i>"}}]}', '{"email":{"font":"Georgia, ''Times New Roman'', serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":18,"line_height":1.7,"text":"#292524","muted":"#78716c","bg":"#f5f5f4","content_bg":"#ffffff","accent":"#d97706","link":"#b45309","button_bg":"#292524","button_text":"#ffffff","border":"#e7e5e4","radius":8,"width":580,"spacing":18}}', 0, 'Welcome', 1793000000019, 1793000000019);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_welcome_start_here', NULL, 'Welcome + start here', 'welcome', 'Branded welcome with a hero, three “start here” posts, what’s coming, and a referral block.', '{"blocks":[{"id":"welc3","type":"section","data":{"blocks":[{"id":"welc1","type":"heading","data":{"level":1,"html":"You’re in! 🎉","align":"center"}},{"id":"welc2","type":"paragraph","data":{"html":"Welcome to {{publication.name}}, {{subscriber.first_name|friend}}.","align":"center"}}],"style":{"bg":"#dbeafe","padding":32,"radius":14}}},{"id":"welc4","type":"paragraph","data":{"html":"Every week you’ll get one email with the ideas, tools and stories worth your time. Here’s the best place to start:"}},{"id":"welc5","type":"heading","data":{"level":3,"html":"Start here"}},{"id":"welc6","type":"list","data":{"ordered":true,"items":["<a href=\"https://example.com\"><b>Our most popular post</b></a> — what it is and why people love it","<a href=\"https://example.com\"><b>The post that explains our point of view</b></a>","<a href=\"{{publication.url}}\"><b>Browse the full archive</b></a>"]}},{"id":"welc7","type":"button","data":{"label":"Visit the website","url":"{{publication.url}}","align":"center"}},{"id":"welc8","type":"heading","data":{"level":3,"html":"Make sure you get every issue"}},{"id":"welc9","type":"list","data":{"ordered":false,"items":["Gmail: drag this email to the Primary tab","Apple Mail: add us to your VIPs","Everywhere else: add our address to your contacts"]}},{"id":"welca","type":"referral","data":{"title":"Know someone who’d like this? Share your link"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.65,"text":"#0f172a","muted":"#64748b","bg":"#eff6ff","content_bg":"#ffffff","accent":"#2563eb","link":"#1d4ed8","button_bg":"#2563eb","button_text":"#ffffff","border":"#dbeafe","radius":14,"width":620,"spacing":16}}', 0, 'Welcome', 1793000000020, 1793000000020);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_welcome_premium', NULL, 'Welcome to premium', 'welcome', 'Thank-you email for new paid members: what’s unlocked, how to access it, and how to manage the subscription.', '{"blocks":[{"id":"welc3","type":"section","data":{"blocks":[{"id":"welc1","type":"paragraph","data":{"html":"<b>★ MEMBER</b>","align":"center"}},{"id":"welc2","type":"heading","data":{"level":1,"html":"Thank you for supporting {{publication.name}}","align":"center"}}],"style":{"bg":"#fef3c7","padding":30,"radius":12}}},{"id":"welc4","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}}, your membership is active. You make this work possible — thank you."}},{"id":"welc5","type":"heading","data":{"level":3,"html":"What’s unlocked"}},{"id":"welc6","type":"list","data":{"ordered":false,"items":["Every premium post and the full archive","Members-only deep dives and templates","Comments and the members community"]}},{"id":"welc7","type":"button","data":{"label":"Explore premium posts","url":"{{publication.url}}","align":"center"}},{"id":"welc8","type":"heading","data":{"level":3,"html":"Good to know"}},{"id":"welc9","type":"paragraph","data":{"html":"Log in on the website with this email address to read premium posts in your browser. You can update, pause or cancel any time from your account page."}},{"id":"welca","type":"paragraph","data":{"html":"Welcome aboard,<br>{{publication.name}}"}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":16,"line_height":1.65,"text":"#1c1917","muted":"#78716c","bg":"#1c1917","content_bg":"#ffffff","accent":"#ca8a04","link":"#a16207","button_bg":"#1c1917","button_text":"#fde68a","border":"#e7e5e4","radius":12,"width":600,"spacing":16}}', 0, 'Welcome', 1793000000021, 1793000000021);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_nudge_reengage', NULL, 'We miss you (re-engagement)', 'automation', 'Win back inactive readers: friendly check-in, best recent posts, and a one-click way to stay subscribed.', '{"blocks":[{"id":"nudg1","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}},"}},{"id":"nudg2","type":"paragraph","data":{"html":"We haven’t seen you open {{publication.name}} in a while — totally fine, inboxes are busy. Here’s what you missed:"}},{"id":"nudg3","type":"list","data":{"ordered":false,"items":["<a href=\"https://example.com\"><b>Recent post one</b></a>","<a href=\"https://example.com\"><b>Recent post two</b></a>","<a href=\"https://example.com\"><b>Recent post three</b></a>"]}},{"id":"nudg4","type":"paragraph","data":{"html":"Still want to hear from us? Click below and we’ll keep you on the list."}},{"id":"nudg5","type":"button","data":{"label":"Yes, keep me subscribed","url":"{{publication.url}}","align":"center"}},{"id":"nudg6","type":"paragraph","data":{"html":"If not, no hard feelings — you can unsubscribe with the link at the bottom of this email."}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","font_size":16,"line_height":1.65,"text":"#1f2937","muted":"#6b7280","bg":"#f9fafb","content_bg":"#ffffff","accent":"#0ea5e9","link":"#0369a1","button_bg":"#0ea5e9","button_text":"#ffffff","border":"#e5e7eb","radius":12,"width":580,"spacing":16}}', 0, 'Automation', 1793000000022, 1793000000022);
INSERT OR IGNORE INTO templates (id, pub_id, name, kind, description, content, style, is_default, category, created_at, updated_at) VALUES ('tpl_lib_upgrade_pitch', NULL, 'Upgrade to premium pitch', 'automation', 'Convert engaged free readers: what premium includes, a testimonial, a limited-time offer and a clear CTA.', '{"blocks":[{"id":"upgr1","type":"paragraph","data":{"html":"Hi {{subscriber.first_name|there}},"}},{"id":"upgr2","type":"paragraph","data":{"html":"You’ve been reading {{publication.name}} for a while now — thank you. I wanted to tell you about premium."}},{"id":"upgr5","type":"section","data":{"blocks":[{"id":"upgr3","type":"heading","data":{"level":3,"html":"Premium members get"}},{"id":"upgr4","type":"list","data":{"ordered":false,"items":["Every deep dive and the full archive","Members-only templates and resources","Early access to events"]}}],"style":{"bg":"#f5f3ff","padding":20,"radius":14}}},{"id":"upgr6","type":"quote","data":{"html":"“The premium issues paid for themselves in the first month.”","cite":"A premium member","style":{"variant":"line","border_color":"#7c3aed"}}},{"id":"upgr7","type":"paragraph","data":{"html":"For the next 72 hours you can join at <b>20% off</b> your first year."}},{"id":"upgr8","type":"button","data":{"label":"Upgrade to premium","url":"{{publication.url}}/upgrade","align":"center"}},{"id":"upgr9","type":"paragraph","data":{"html":"Either way, I’m glad you’re here."}}]}', '{"email":{"font":"''Helvetica Neue'', Helvetica, Arial, sans-serif","heading_font":"Georgia, ''Times New Roman'', serif","font_size":16,"line_height":1.65,"text":"#111827","muted":"#6b7280","bg":"#f5f3ff","content_bg":"#ffffff","accent":"#7c3aed","link":"#6d28d9","button_bg":"#7c3aed","button_text":"#ffffff","border":"#ede9fe","radius":14,"width":600,"spacing":16}}', 0, 'Automation', 1793000000023, 1793000000023);
UPDATE posts SET style = json_remove(style, '$.email.font') WHERE template_id IS NOT NULL AND json_valid(style) AND json_extract(style, '$.email.font') IS NOT NULL AND json_extract(style, '$.email.font') = (SELECT json_extract(t.style, '$.email.font') FROM templates t WHERE t.id = posts.template_id AND json_valid(t.style));
